// Semana anterior: de hace 7 días a ayer (formato AAAA-MM-DD)
const hoy = new Date();
const fmt = d => d.toISOString().slice(0, 10);
const hasta = new Date(hoy); hasta.setDate(hoy.getDate() - 1);
const desde = new Date(hoy); desde.setDate(hoy.getDate() - 7);

return [{ json: { desde: fmt(desde), hasta: fmt(hasta) } }];

// Convierte la respuesta de /api/reportes/dashboard en un correo HTML
const d = $input.first().json;
const r = d.resumen;
const v = d.variacion;
const mxn = n => Number(n || 0).toLocaleString('es-MX', { style: 'currency', currency: 'MXN' });
const delta = x => x === null || x === undefined ? 'nuevo' : (x > 0 ? '▲ ' : x < 0 ? '▼ ' : '') + Math.abs(x) + '%';
const color = x => x > 0 ? '#15803d' : x < 0 ? '#b91c1c' : '#6b7280';

const kpi = (titulo, valor, variacion) => `
  <td style="padding:12px;border:1px solid #e5e7eb;border-radius:8px;">
    <div style="font-size:12px;color:#6b7280;">${titulo}</div>
    <div style="font-size:20px;font-weight:700;margin:4px 0;">${valor}</div>
    <div style="font-size:12px;color:${color(variacion)};">${delta(variacion)} vs semana previa</div>
  </td>`;

const filasTop = d.productosTop.productos.map(p => `
  <tr>
    <td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;">${p.posicion}. ${p.nombre}</td>
    <td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;text-align:right;">${p.unidades}</td>
    <td style="padding:6px 8px;border-bottom:1px solid #f3f4f6;text-align:right;">${mxn(p.ingresos)}</td>
  </tr>`).join('') || '<tr><td colspan="3" style="padding:8px;color:#6b7280;">Sin ventas en la semana</td></tr>';

const estados = d.estados.estados.map(e => `${e.etiqueta}: <b>${e.cantidad}</b> (${e.porcentaje}%)`).join(' · ');

const html = `
<div style="font-family:Segoe UI,Arial,sans-serif;max-width:640px;margin:auto;color:#111827;">
  <div style="background:#0f766e;color:#fff;padding:18px 22px;border-radius:10px 10px 0 0;">
    <div style="font-size:12px;letter-spacing:2px;opacity:.85;">TIENDA 5M · REPORTE SEMANAL</div>
    <div style="font-size:20px;font-weight:700;">${d.rango.desde} al ${d.rango.hasta}</div>
  </div>
  <div style="border:1px solid #e5e7eb;border-top:none;padding:20px 22px;border-radius:0 0 10px 10px;">
    <table role="presentation" width="100%" cellspacing="8"><tr>
      ${kpi('Ingresos', mxn(r.ingresos), v.ingresos)}
      ${kpi('Pedidos pagados', r.pedidos, v.pedidos)}
    </tr><tr>
      ${kpi('Ticket por pedido', mxn(r.ticketPromedioPedido), v.ticketPromedioPedido)}
      ${kpi('Ticket por cliente', mxn(r.ticketPromedioCliente), v.ticketPromedioCliente)}
    </tr></table>
    <h3 style="font-size:15px;margin:18px 0 6px;">Top 5 productos</h3>
    <table width="100%" style="border-collapse:collapse;font-size:13px;">
      <tr style="background:#f3f4f6;"><th style="text-align:left;padding:6px 8px;">Producto</th><th style="text-align:right;padding:6px 8px;">Unidades</th><th style="text-align:right;padding:6px 8px;">Monto</th></tr>
      ${filasTop}
    </table>
    <p style="font-size:13px;margin:16px 0 0;">Pedidos por estado: ${estados}</p>
    <p style="font-size:12px;color:#6b7280;margin:14px 0 0;">Generado automáticamente por n8n a partir de /api/reportes/dashboard.</p>
  </div>
</div>`;

return [{ json: {
  asunto: `Reporte semanal Tienda 5M: ${mxn(r.ingresos)} en ${r.pedidos} pedidos (${d.rango.desde} – ${d.rango.hasta})`,
  html,
  texto: `Ingresos ${mxn(r.ingresos)} (${delta(v.ingresos)}), ${r.pedidos} pedidos, ticket ${mxn(r.ticketPromedioPedido)}`
} }];
